    AND EXISTS (SELECT 1 FROM projects AS duplicate WHERE duplicate.name = projects.name AND duplicate.archived = 0);
  DELETE FROM projects WHERE id NOT IN (SELECT MIN(id) FROM projects GROUP BY name);
`);

